static void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
template<class F>static void refuses(F call,const char*message){bool failed=false;try{call();}catch(const std::exception&){failed=true;}check(failed,message);}
static bool same(const SceneVertexShadingCandidate&a,const SceneVertexShadingCandidate&b){return a.normal==b.normal&&a.tangent==b.tangent&&a.previewLightColor==b.previewLightColor&&a.model==b.model&&a.sourceVertex==b.sourceVertex&&a.origin==b.origin&&a.hasNormal==b.hasNormal&&a.hasTangent==b.hasTangent&&a.hasPreviewLightColor==b.hasPreviewLightColor;}
static void samePacket(const PreparedSessionSceneCandidate&a,const PreparedSessionSceneCandidate&b){
 check(a.upload.vertices.size()==b.upload.vertices.size()&&a.upload.indices==b.upload.indices&&a.upload.opaque.size()==b.upload.opaque.size()&&a.upload.translucent.size()==b.upload.translucent.size()&&a.upload.materials.size()==b.upload.materials.size()&&a.materialAlpha==b.materialAlpha&&a.materialInputs.size()==b.materialInputs.size()&&a.materialInputs.owners.size()==b.materialInputs.owners.size()&&a.materialInputs.alpha.size()==b.materialInputs.alpha.size()&&a.upload.vertexShading.size()==b.upload.vertexShading.size(),"packet rollback dimensions");
 for(size_t i=0;i<a.upload.vertices.size();++i)check(!std::memcmp(&a.upload.vertices[i],&b.upload.vertices[i],36),"packet legacy vertex bytes");
 for(size_t i=0;i<a.upload.vertexShading.size();++i)check(same(a.upload.vertexShading[i],b.upload.vertexShading[i]),"packet shading rollback");
 for(const auto lists:{std::make_pair(&a.upload.opaque,&b.upload.opaque),std::make_pair(&a.upload.translucent,&b.upload.translucent)})for(size_t i=0;i<lists.first->size();++i)check(!std::memcmp(&lists.first->at(i),&lists.second->at(i),sizeof(SceneGpuDrawCandidate)),"draw bytes rollback");
 for(size_t i=0;i<a.upload.materials.size();++i)check(a.upload.materials[i].model==b.upload.materials[i].model&&a.upload.materials[i].material==b.upload.materials[i].material,"material identity rollback");
}
